        'map、filter、foldLeft 都是「高階函數」（higher-order function：接受函式當參數，或回傳函式的函式）在 JS 裡的直接對應：map 對陣列每個元素套用同一個轉換函式產生等長新陣列；filter 用回傳布林值的判斷函式挑出符合條件的元素；foldLeft（對應 JS 的 reduce）則是帶著一個累加值，逐一走訪陣列元素把結果收斂成單一值，三者都不修改原陣列。',
