        'currying（柯里化）就是把一個多參數函式，轉換成一連串每次只接收一個參數、彼此回傳彼此的單參數函式鏈（在 JS 就是連續回傳箭頭函式，如 a => b => c => 結果）；重點不是語法炫技，而是讓呼叫端可以在程式的不同地方分別決定每個參數，減少重複傳遞相同引數的樣板碼。',
