        '用「去超市買菜」示範寫程式前如何先用 ACD 分析問題：檢查冰箱是 action（產出「目前庫存」這筆 data）、開車去店裡是 action、決定要買什麼則是把「想要的庫存 減去 目前庫存」算成購物清單的 calculation——很多這類決策其實原本都「在腦中」發生，從沒被明確寫下來，一旦意識到這點，就更容易在既有流程裡找出隱藏的 calculations。',
