        '「盡量減少隱性輸入輸出」原則不是只有 calculation 才適用：即使是 action，也該把讀取全域變數改成明確參數、把輸出改成回傳值。update_shipping_icons() 從直接讀取全域 shopping_cart 改成接受 cart 參數，calc_cart_total() 也把 shopping_cart_total 的賦值內縮到函式內部處理，藉此提升可測試性與可重用性。',
