        '「設計就是把東西拆開」原則：add_item() 表面上只做一件事，實際上同時做了複製陣列、建立 item 物件、把 item 塞進複製陣列、回傳複製陣列四件事。把「建立 item 物件」拆成獨立的 make_cart_item()，讓知道 cart 結構的部分與知道 item 結構的部分分開，兩種資料結構可以各自獨立演化（例如未來把 cart 從陣列換成雜湊表）。',
