        '書中用 C（cart）、I（item）、B（business rule）、A（array utility）替每個函式標記類別，藉此觀察出「層級」的雛形：像 calc_total() 這種函式其實同時知道 cart 結構、也定義了 MegaMart 的商業規則，這種身兼多重身分的函式，正是後續第 8、9 章要拆解成獨立分層的訊號。',
