        '數字等基本表達式可用運算子（如 + 、 * ）組成複合表達式（組合式），JavaScript 採中序記法並遵守運算子優先權與左結合規則，複合表達式還能無限層層嵌套。',
        'const 宣告是最簡單的抽象手段：把運算結果的值跟一個名稱綁在一起存進「環境」，之後就能用名稱代替重複描述細節。',
        '求值運算子組合式的規則本身是遞迴的——先求值每個運算元、再套用運算子——可以畫成樹狀圖表示數值由末端節點往上層層累積的過程。',
        '函式宣告（如 square、sum_of_squares）把一段複合運算包裝成一個可重複使用的單元；理解函式套用的初步方法是代換模型：把參數逐一替換成引數再化簡表達式，但這只是輔助思考的簡化模型，不代表直譯器真正的運作方式。',
        '牛頓法求平方根的例子（sqrt_iter、improve、is_good_enough）示範函式可以當「黑盒子」使用：只要回傳結果一致，函式內部怎麼實作、參數叫什麼名字（區域變數的作用域／bound name）都不影響使用者，這也是把輔助函式包進區塊結構、隱藏在外層函式內部的動機。',
        'JavaScript 採用「先求值引數再套用函式」的 applicative-order evaluation，不同於「完全展開表達式後才化簡」的 normal-order evaluation；兩者對能用代換模型描述的合法運算會得到相同結果，但求值的中間過程與重複運算次數不同。',
