        'compound_apply 用函式的參數與 argl 中的實際引數擴展環境後求值函式本體，並把 continue 預設指向 return_undefined，因此函式本體如果沒有明確執行 return 就結束，回傳值自然是 undefined。',
        '可以用第 5.2 節的堆疊統計功能實際跑這台機器，量出遞迴 factorial 與疊代 factorial 在堆疊深度上的差異（疊代版深度固定、遞迴版隨 n 增長），把第 1、5.1 節裡「疊代 vs 遞迴」的抽象概念變成可以實測驗證的數字。',
