        '編譯器 compile 函式的語法 case 分析結構跟直譯器的 eval_dispatch 幾乎一樣，但差別在於：直譯器每次執行都要重新判斷元件類型、重新分析語法，編譯器只在編譯當下分析一次，之後產生的目的碼（object code）可以重複執行任意次而不用再分析——這是編譯比直譯快的根本原因。',
        '每個程式碼產生器除了元件本身，還額外帶兩個參數：target（結果要放進哪個暫存器）與 linkage（執行完後要「接著下一條指令」「跳回 continue」還是「跳到某個標籤」），讓同一段元件的編譯邏輯可以視所在的呼叫情境彈性接續不同後續動作。',
        '組合指令序列時用 append_instruction_sequences 單純串接，但涉及暫存器保存時改用 preserving：它會分析兩段序列各自「需要」與「會修改」哪些暫存器，只有前段真的會覆寫、且後段真的需要該值時才插入 save/restore，不像直譯器保守地每次都全部存起來，因此能省下大量不必要的堆疊操作。',
        '編譯出的函式呼叫（compile_fun_appl）沿用跟顯式控制直譯器一樣的 push_marker_to_stack／continue 暫存器機制，並在 target 是 val、linkage 是 return 時刻意不多做一次 continue 的 save，讓編譯出的尾呼叫同樣能以常數堆疊空間執行；書中實測直譯執行 factorial(5) 需要 151 次堆疊推入、最大深度 28，同一函式編譯後只需要 36 次推入、最大深度 14，具體展示了這些優化帶來的效率差距。',
        '5.5.6 節的詞法定址（lexical addressing）進一步優化名稱查找：因為語言是詞法作用域，編譯器可以在編譯時就靠一個「編譯期環境」推算出某個名稱在執行期會落在往外數第幾層 frame、第幾個位置，用固定的 (frame 數, 位移) 兩個數字直接存取，取代逐層逐名稱比對的 lookup_symbol_value 搜尋。',
        '5.5.7 節示範如何讓編譯碼與直譯器整合成一個系統：compile_and_go 把編譯結果組譯成指令、灌進直譯器機器的 val 暫存器並設定 flag 跳到特別的 external_entry 入口執行，使得編譯過的函式與直譯執行的函式可以在同一個執行環境裡互相呼叫。',
