        'bounded context 之間傳遞的不是內部使用的 Domain Object，而是專門設計來序列化的 DTO：輸入邊界（gate）負責把不受信任的外部資料驗證轉換成受信任的領域物件，輸出邊界則刻意「遺漏」敏感資訊，例如出貨 context 根本不需要知道客戶的信用卡卡號。',
