        '作者提出「confidence（信任）」的核心主張：能透過閱讀、推理就確認程式碼會做什麼，才是真正信任程式碼；只靠跑測試套件通過就安心，是一種心存僥倖，FP 的價值在於讓程式碼本身可驗證、可推理。',
