        '全書收尾強調：這個範例的重點不是提供一套該照抄的寫法，而是展示如何把前面十章的個別技巧（curry、pipe/compose、immutability、reduce/map/zip/each、Observable）整合在同一段真實情境的程式碼裡協同運作。',
