        'this 的值取決於函式如何被呼叫，而非如何被定義：當函式作為物件方法被呼叫時（obj.method()），this 指向該物件；作為獨立函式呼叫時，非嚴格模式下指向全域物件，嚴格模式下為 undefined。',
        '箭頭函式與一般函式根本不同，它繼承外層作用域的 this 值並永久綁定，無法透過 call()、apply()、bind() 方法改變其 this，這使箭頭函式特別適合用作回呼函式以保留上下文。',
