        '四種並行 Promise 組合方法各有不同用途：Promise.all() 要求全部成功、Promise.any() 只要任何一個成功就解決、Promise.race() 回傳第一個完成（無論成功或失敗）的結果、Promise.allSettled() 等待全部完成並回傳詳細狀態。',
