        'JSX 比 HTML 更嚴格：自我封閉標籤（如 <img>）必須寫成 <img />，容器標籤也要完整封閉，不能像 HTML 那樣省略結尾標籤；屬性名稱要改用駝峰式命名（如 strokeWidth）、class 要改成 className（但 aria-*／data-* 例外，仍維持連字號格式）。',
