        '看到 {{backgroundColor: \'black\'}} 這種雙大括號寫法時，第一層是 JSX 的表達式標記，第二層才是 JavaScript 物件字面值——這是傳 inline style 物件時的固定寫法，且 CSS 屬性名稱一樣要改成駝峰式（如 backgroundColor）。',
