        'Context 透過 createContext()、useContext()、Provider 三步驟解決 prop drilling（一路手動往下傳 props）的問題：先建立 context 物件，需要資料的元件用 useContext() 讀取，祖先元件用 Provider 包住子樹提供值，資料就能跨越任意層級的中間元件直接傳遞。',
