        'ref 跟 state 的關鍵差異：state 改變會觸發重新渲染，且每次渲染讀到的都是那次的快照值；ref 則是一個普通的可變物件，改變不會觸發渲染，因此不該在渲染過程中讀寫 ref.current。',
