        'Error Boundary 並非萬能：事件處理函式（onClick 等）裡的錯誤、setTimeout/requestAnimationFrame 這類非同步程式碼裡的錯誤、伺服器端渲染時的錯誤、以及 Error Boundary 自己程式碼本身丟出的錯誤，這四種情況都不會被攔截到。',
